from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Initialize an empty list to store separated groups
    separated_groups = []

    # Iterate through the input string
    i = 0
    while i < len(paren_string):
        # Identify and extract each group of nested parentheses
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while j < len(paren_string):
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                if count == 0:
                    separated_groups.append(paren_string[i:j+1])
                    i = j
                    break
                j += 1
        i += 1

    # Check if the group is balanced and not nested within each other
    valid_groups = []
    for group in separated_groups:
        stack = []
        is_valid = True
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if stack and stack[-1] == '(':
                    stack.pop()
                else:
                    is_valid = False
                    break
        if is_valid and not stack:
            valid_groups.append(group)

    # Return the list of separated groups
    return valid_groups

